      double precision function dzasum( N, x, strideX )
        implicit none
        integer :: N, strideX
        complex(kind=kind(0.0d0)) :: x( * )
        integer :: i
        double precision :: stemp
        intrinsic abs, dble, aimag
        stemp = 0.0d0
        stemp = stemp + abs( dble( x( 1 ) ) ) + abs( aimag( x( 1 ) ) )
        dzasum = stemp
        return
      end function dzasum
